#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCndEngine: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = CndEngine

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> CndEngine {
        return CndEngine(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: CndEngine) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CndEngine {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: CndEngine, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCndEngine_lift(_ pointer: UnsafeMutableRawPointer) throws -> CndEngine {
    return try FfiConverterTypeCndEngine.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCndEngine_lower(_ value: CndEngine) -> UnsafeMutableRawPointer {
    return FfiConverterTypeCndEngine.lower(value)
}




public struct CatalogFilter {
    public var kind: String
    public var sourceId: Int64?
    public var query: String
    public var groupTitle: String?
    public var host: String?
    public var favoritesOnly: Bool
    public var sortBy: SortField
    public var sortAsc: Bool
    public var limit: UInt32
    public var offset: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(kind: String, sourceId: Int64?, query: String, groupTitle: String?, host: String?, favoritesOnly: Bool, sortBy: SortField, sortAsc: Bool, limit: UInt32, offset: UInt32) {
        self.kind = kind
        self.sourceId = sourceId
        self.query = query
        self.groupTitle = groupTitle
        self.host = host
        self.favoritesOnly = favoritesOnly
        self.sortBy = sortBy
        self.sortAsc = sortAsc
        self.limit = limit
        self.offset = offset
    }
}

#if compiler(>=6)
extension CatalogFilter: Sendable {}
#endif


extension CatalogFilter: Equatable, Hashable {
    public static func ==(lhs: CatalogFilter, rhs: CatalogFilter) -> Bool {
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.sourceId != rhs.sourceId {
            return false
        }
        if lhs.query != rhs.query {
            return false
        }
        if lhs.groupTitle != rhs.groupTitle {
            return false
        }
        if lhs.host != rhs.host {
            return false
        }
        if lhs.favoritesOnly != rhs.favoritesOnly {
            return false
        }
        if lhs.sortBy != rhs.sortBy {
            return false
        }
        if lhs.sortAsc != rhs.sortAsc {
            return false
        }
        if lhs.limit != rhs.limit {
            return false
        }
        if lhs.offset != rhs.offset {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(kind)
        hasher.combine(sourceId)
        hasher.combine(query)
        hasher.combine(groupTitle)
        hasher.combine(host)
        hasher.combine(favoritesOnly)
        hasher.combine(sortBy)
        hasher.combine(sortAsc)
        hasher.combine(limit)
        hasher.combine(offset)
    }
}



