public enum CndError: Swift.Error {

    
    
    case Database(message: String
    )
    case Network(message: String
    )
    case Parse(message: String
    )
    case Io(message: String
    )
    case Internal(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCndError: FfiConverterRustBuffer {
    typealias SwiftType = CndError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CndError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Database(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Network(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Parse(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CndError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Database(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Network(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Parse(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Io(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCndError_lift(_ buf: RustBuffer) throws -> CndError {
    return try FfiConverterTypeCndError.lift(buf)
}

